sys_script_include.script:
var HoCOHSMFluClinicAjax = Class.create();

HoCOHSMFluClinicAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    alreadyHaveAppointment: function() {
        var user = this.getParameter('sysparm_user');
        var reason = this.getParameter('sysparm_reason');
        var userType = this.getParameter('sysparm_usertype');
        var gr;


        if (userType == 'external') {
            gr = new GlideRecord('customer_contact');

            gr.get('email', user);
            gr.query();

            user = [];
            while (gr.next()) {
                user.push(gr.getValue('sys_id'));
            }
        }

        gr = new GlideRecordSecure('x_hccc_hoc_ohs_vaccination_appointment');

        gr.addEncodedQuery('stateNOT IN3,4,7^active=true');
        gr.addQuery('contact', 'IN', user);
		gr.addEncodedQuery('window_end>=javascript:gs.beginningOfToday()');
		// both vaccines 
		if (reason != 'e86617541b7df9989fde86acdd4bcbd8') {
			 gr.addEncodedQuery('reason=e86617541b7df9989fde86acdd4bcbd8^ORreason=' + reason);
		}

        gr.setLimit(1);
        gr.query();

        if (gr.next()) {
            return gr.sys_id.toString();
        }
        return null;
    },



    alreadyHaveAppointmentMyself: function() {
        //var userSysId = gs.getUserID();
        var gr = new GlideRecordSecure('x_hccc_hoc_ohs_vaccination_appointment');
        var reason = this.getParameter('sysparm_reason');

        gr.addEncodedQuery('stateNOT IN3,4,7^active=true^contactDYNAMIC90d1921e5f510100a9ad2572f2b477fe');
        gr.query();
        return gr.getRowCount() >= 1;

    },
    alreadyHaveAppointmentInternal: function() {
        var userSysId = this.getParameter('sysparm_employee');
        var gr = new GlideRecordSecure('x_hccc_hoc_ohs_vaccination_appointment');

        gr.addEncodedQuery('stateNOT IN3,4,7^active=true');
        gr.addQuery('contact', userSysId);
        gr.query();

        /*
        try {
            var grUser = new GlideRecord('sys_user');

grUser.get(userSysId);
gs.info("Check for user: " + userSysId +
    "\r\nUserID: " + grUser.getDisplayValue('user_name') + "\r\nemail: " + grUser.getDisplayValue('email') +
    "\r\n\r\nreturns " + gr.getRowCount());
        } catch (e) {
            gs.error(e)
        }
		gr.next();
        gs.info("Appointment #" + gr.getValue('number') +
            "\r\nID: " + gr.getUniqueValue() +
            "\r\ncontact: " + gr.getValue('contact') +
            "\r\nstate: " + gr.getValue('state') +
            "\r\nsys_created_by: " + gr.getValue('sys_created_by') +
            "\r\nsys_created_on: " + gr.getValue('sys_created_on'));*/
        return gr.getRowCount() >= 1;
    },
    alreadyHaveAppointmentExternal: function() {
        var email = this.getParameter('sysparm_email');
        //Retrieve contacts that use the email address (Should be only one in theory)
        var array = [];
        var gr = new GlideRecord('customer_contact');

        gr.get('email', email);
        gr.query();

        while (gr.next()) {
            array.push(gr.getValue('sys_id'));
        }

        //Find non-completed appointments that are assigned to the contact(s) with the email address
        var gr2 = new GlideRecordSecure('x_hccc_hoc_ohs_vaccination_appointment');

        gr2.addQuery('contact', 'IN', array);
        gr2.addEncodedQuery('stateNOT IN3,4,7^active=true');
        gr2.query();
        return gr2.getRowCount() >= 1; //Return a boolean that tells if there is an appointment already
    },
    /*
    returns the user type
     */
    getUserType: function() {
        var gr = new GlideRecord("sys_user");

        gr.get(gs.getUserID());
        return gr.getValue("x_hccc_base_user_type");
    },


	//check if nurse
	checkIfNurse: function() {
		return gs.getUser().isMemberOf('CEH-HRS-OHS-Vaccination Nurses'); 
	},

    /*
    To use in dynamic filter like so: javascript: user is new x_hccc_hoc_ohs.HoCOHSMFluClinicAjax().getMPStaffList()
     */
    getMPStaffList: function() {
        var sysIdArray = []; //numberINWUA0002035,WUA0002034
        var gr = new GlideRecord("sys_user");

        gr.addQuery('x_hccc_base_user_type', 'mp_staff');
        gr.addQuery('active', 'true');
        gr.query();
        while (gr.next()) {
            sysIdArray.push(gr.getUniqueValue());
        }

        //return sysIdArray.join(',');
        return sysIdArray;
    },
    type: 'HoCOHSMFluClinicAjax'
});
